<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>AYOUB.EXE — Ayoub Rechouk, Web Developer</title>
<meta name="description" content="Ayoub Rechouk — Web Development student in Agadir, Morocco. PHP, Python, JavaScript, MySQL. Open to opportunities.">
<style>
/* ============================================================
   TOKENS
   ============================================================ */
:root{
  --void: #0B0C10;
  --panel: #14161B;
  --panel-raised: #1B1E24;
  --line: #2A2E36;
  --line-soft: #1F2229;
  --ink: #EDEEF0;
  --ink-dim: #8A8F98;
  --ink-faint: #565B64;
  --amber: #E8A33D;
  --amber-dim: rgba(232,163,61,0.14);
  --amber-line: rgba(232,163,61,0.4);
  --green: #6FCF97;
  --red: #E1654A;

  --font-display: 'Space Grotesk', 'Segoe UI', Arial, sans-serif;
  --font-body: 'Inter', 'Segoe UI', Arial, sans-serif;
  --font-mono: 'JetBrains Mono', 'SF Mono', Consolas, monospace;

  --container: 1120px;
}

@import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;700&family=Inter:wght@400;500;600&family=JetBrains+Mono:wght@400;500;700&display=swap');

*{ box-sizing:border-box; margin:0; padding:0; }
html{ scroll-behavior:smooth; }
@media (prefers-reduced-motion: reduce){
  html{ scroll-behavior:auto; }
  *{ animation-duration:0.01ms !important; animation-iteration-count:1 !important; transition-duration:0.01ms !important; }
}

body{
  background: var(--void);
  color: var(--ink);
  font-family: var(--font-body);
  line-height:1.6;
  -webkit-font-smoothing:antialiased;
  overflow-x:hidden;
}

body.crt-on::before{
  content:"";
  position:fixed; inset:0;
  z-index:9000;
  pointer-events:none;
  background: repeating-linear-gradient(
    to bottom,
    rgba(0,0,0,0) 0px,
    rgba(0,0,0,0.12) 1px,
    rgba(0,0,0,0) 2px
  );
}
body.crt-on::after{
  content:"";
  position:fixed; inset:0;
  z-index:9001;
  pointer-events:none;
  background: radial-gradient(ellipse at center, rgba(0,0,0,0) 55%, rgba(0,0,0,0.55) 100%);
}

a{ color:inherit; text-decoration:none; }
img{ max-width:100%; display:block; }
button{ font-family:inherit; cursor:pointer; }

.container{ max-width:var(--container); margin:0 auto; padding:0 28px; }

::selection{ background: var(--amber); color:#0B0C10; }

/* focus states — accessibility */
a:focus-visible, button:focus-visible, input:focus-visible{
  outline: 2px solid var(--amber);
  outline-offset: 3px;
  border-radius:2px;
}

/* ============================================================
   BOOT SCREEN (1986 homage — first-visit intro)
   ============================================================ */
#boot{
  position:fixed; inset:0; z-index:10000;
  background:#000;
  color:#8FE39A;
  font-family:var(--font-mono);
  font-size:15px;
  padding: 48px;
  display:flex; flex-direction:column; justify-content:center;
  max-width:none;
}
#boot .boot-inner{ max-width:640px; margin:0 auto; width:100%; }
#boot .boot-line{ opacity:0; white-space:pre-wrap; margin-bottom:6px; animation: boot-in 0.15s forwards; }
#boot .cursor{ display:inline-block; width:9px; height:16px; background:#8FE39A; vertical-align:-2px; animation: blink 1s steps(1) infinite; }
@keyframes boot-in{ to{ opacity:1; } }
@keyframes blink{ 50%{ opacity:0; } }
#boot .skip{
  position:absolute; bottom:36px; right:40px;
  font-family:var(--font-mono); font-size:12px; color:#4E7256;
  background:transparent; border:1px solid #2C4A32; padding:8px 14px;
  opacity:0; transition:opacity .4s ease;
}
#boot .skip.show{ opacity:1; }
#boot .skip:hover{ color:#8FE39A; border-color:#4E7256; }
#boot.hide{ animation: boot-out .5s ease forwards; }
@keyframes boot-out{ to{ opacity:0; visibility:hidden; } }

/* ============================================================
   NAV
   ============================================================ */
header.site-nav{
  position:fixed; top:0; left:0; right:0; z-index:500;
  background:rgba(11,12,16,0.82);
  backdrop-filter: blur(10px);
  border-bottom:1px solid var(--line-soft);
}
.nav-row{ display:flex; align-items:center; justify-content:space-between; height:64px; }
.nav-mark{ font-family:var(--font-mono); font-weight:700; font-size:15px; letter-spacing:0.02em; }
.nav-mark span{ color:var(--amber); }
.nav-links{ display:flex; gap:6px; list-style:none; }
.nav-links a{
  font-family:var(--font-mono); font-size:13px; color:var(--ink-dim);
  padding:8px 14px; border-radius:6px; transition:color .2s, background .2s;
}
.nav-links a:hover{ color:var(--ink); background:var(--panel-raised); }
.nav-status{ display:flex; align-items:center; gap:8px; font-family:var(--font-mono); font-size:12px; color:var(--green); }
.nav-status .dot{ width:6px; height:6px; border-radius:50%; background:var(--green); box-shadow:0 0 6px var(--green); }

@media (max-width:900px){
  .nav-status{ display:none; }
}
@media (max-width:640px){
  .nav-row{ height:auto; padding:14px 0; flex-wrap:wrap; gap:10px; justify-content:center; }
  .nav-links{ gap:2px; flex-wrap:wrap; justify-content:center; }
  .nav-links a{ padding:6px 9px; font-size:12px; }
}

/* ============================================================
   HERO
   ============================================================ */
section.hero{
  padding: 168px 0 96px;
  position:relative;
  overflow:hidden;
}
.hero-grid{
  display:grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap:56px;
  align-items:center;
}
.eyebrow{
  display:inline-flex; align-items:center; gap:10px;
  font-family:var(--font-mono); font-size:12.5px; letter-spacing:0.16em;
  text-transform:uppercase; color:var(--amber);
  margin-bottom:22px;
}
.eyebrow::before{ content:""; width:22px; height:1px; background:var(--amber); }
h1.hero-title{
  font-family:var(--font-display); font-weight:700;
  font-size:clamp(40px,6vw,68px);
  line-height:1.02; letter-spacing:-0.01em;
  margin-bottom:18px;
}
.hero-role{
  font-family:var(--font-mono); font-size:16px; color:var(--ink-dim);
  margin-bottom:26px;
}
.hero-role .sep{ color:var(--amber-line); margin:0 8px; }
p.hero-copy{
  font-size:16.5px; color:var(--ink-dim); max-width:480px; margin-bottom:30px;
}
.status-pill{
  display:inline-flex; align-items:center; gap:9px;
  font-family:var(--font-mono); font-size:12.5px;
  border:1px solid var(--amber-line); color:var(--amber);
  padding:8px 14px; border-radius:999px; margin-bottom:34px;
}
.status-pill .dot{ width:6px; height:6px; border-radius:50%; background:var(--amber); box-shadow:0 0 6px var(--amber); animation: pulse 2s infinite; }
@keyframes pulse{ 0%,100%{ opacity:1; } 50%{ opacity:0.4; } }

.hero-actions{ display:flex; gap:12px; flex-wrap:wrap; }
.btn{
  font-family:var(--font-mono); font-size:13px; padding:13px 20px;
  border-radius:8px; border:1px solid var(--line);
  transition: border-color .2s, background .2s, transform .15s;
  display:inline-flex; align-items:center; gap:8px;
}
.btn:hover{ transform:translateY(-1px); }
.btn-primary{ background:var(--amber); border-color:var(--amber); color:#0B0C10; font-weight:700; }
.btn-primary:hover{ background:#f0b459; }
.btn-ghost{ color:var(--ink); background:var(--panel); }
.btn-ghost:hover{ border-color:var(--amber-line); }

/* photo — scan-reveal treatment, not a circle avatar */
.hero-photo-wrap{
  position:relative;
  aspect-ratio: 4/5;
  background: linear-gradient(180deg, var(--panel), var(--panel-raised));
  border:1px solid var(--line);
  border-radius:14px;
  overflow:hidden;
  display:flex; align-items:flex-end; justify-content:center;
}
.hero-photo-wrap .frame-label{
  position:absolute; top:14px; left:16px;
  font-family:var(--font-mono); font-size:11px; color:var(--ink-faint);
  letter-spacing:0.08em; z-index:3;
}
.hero-photo-wrap .frame-label span{ color:var(--amber); }
.hero-photo-wrap img{
  width:88%; height:auto; object-fit:contain; object-position:bottom;
  filter: grayscale(0.15) contrast(1.04);
  position:relative; z-index:2;
}
.hero-photo-wrap .scanline{
  position:absolute; left:0; right:0; height:3px;
  background: linear-gradient(90deg, transparent, var(--amber), transparent);
  box-shadow:0 0 16px 3px var(--amber);
  z-index:3;
  animation: scan-sweep 3.2s ease-in-out infinite;
  opacity:0.85;
}
@keyframes scan-sweep{
  0%{ top:6%; } 50%{ top:92%; } 100%{ top:6%; }
}
.hero-photo-wrap .grid-overlay{
  position:absolute; inset:0; z-index:1;
  background-image:
    linear-gradient(rgba(232,163,61,0.05) 1px, transparent 1px),
    linear-gradient(90deg, rgba(232,163,61,0.05) 1px, transparent 1px);
  background-size: 26px 26px;
}
@media (prefers-reduced-motion: reduce){
  .hero-photo-wrap .scanline{ animation:none; top:50%; }
}

@media (max-width:860px){
  .hero-grid{ grid-template-columns:1fr; }
  .hero-photo-wrap{ max-width:320px; margin:0 auto; order:-1; }
}

/* ============================================================
   SECTION SCAFFOLDING
   ============================================================ */
section{ padding:88px 0; border-top:1px solid var(--line-soft); }
.section-head{ margin-bottom:44px; display:flex; align-items:baseline; gap:16px; flex-wrap:wrap; }
.section-index{ font-family:var(--font-mono); font-size:13px; color:var(--amber); }
h2.section-title{
  font-family:var(--font-display); font-weight:700;
  font-size:clamp(26px,3.4vw,36px); letter-spacing:-0.01em;
}
.section-sub{ font-family:var(--font-mono); font-size:13px; color:var(--ink-faint); margin-left:auto; }

/* ============================================================
   ABOUT — identity terminal
   ============================================================ */
.about-grid{ display:grid; grid-template-columns:1fr 1fr; gap:48px; align-items:start; }
.term-window{
  background:var(--panel); border:1px solid var(--line); border-radius:10px; overflow:hidden;
}
.term-bar{ display:flex; align-items:center; gap:8px; padding:11px 14px; background:var(--panel-raised); border-bottom:1px solid var(--line); }
.term-dot{ width:10px; height:10px; border-radius:50%; }
.term-dot.r{ background:#E1654A; } .term-dot.y{ background:#E8A33D; } .term-dot.g{ background:#6FCF97; }
.term-title{ font-family:var(--font-mono); font-size:12px; color:var(--ink-faint); margin-left:6px; }
.term-body{ padding:20px 22px; font-family:var(--font-mono); font-size:14px; line-height:1.9; }
.term-body .fn{ color:var(--amber); }
.term-body .field{ color:var(--ink-faint); }
.term-body .val{ color:var(--ink); }
.about-copy{ font-size:16px; color:var(--ink-dim); }
.about-copy p{ margin-bottom:16px; }
.about-copy strong{ color:var(--ink); font-weight:600; }

@media (max-width:860px){ .about-grid{ grid-template-columns:1fr; } }

/* ============================================================
   EDUCATION — academic database
   ============================================================ */
.db-list{ display:flex; flex-direction:column; gap:0; border:1px solid var(--line); border-radius:10px; overflow:hidden; }
.db-row{
  display:grid; grid-template-columns:140px 1fr auto; gap:22px; align-items:center;
  padding:22px 24px; border-bottom:1px solid var(--line-soft);
  background:var(--panel);
}
.db-row:last-child{ border-bottom:none; }
.db-years{ font-family:var(--font-mono); font-size:13px; color:var(--amber); }
.db-name{ font-family:var(--font-display); font-weight:700; font-size:17px; margin-bottom:4px; }
.db-detail{ font-size:14.5px; color:var(--ink-dim); }
.db-status{
  font-family:var(--font-mono); font-size:11px; letter-spacing:0.06em;
  padding:5px 10px; border-radius:5px; white-space:nowrap;
}
.db-status.current{ color:var(--green); border:1px solid rgba(111,207,151,0.35); background:rgba(111,207,151,0.08); }
.db-status.done{ color:var(--ink-faint); border:1px solid var(--line); }

@media (max-width:640px){
  .db-row{ grid-template-columns:1fr; gap:8px; }
  .db-status{ width:fit-content; }
}

/* ============================================================
   EXPERIENCE — system log
   ============================================================ */
.log-entry{ border:1px solid var(--line); border-radius:10px; padding:26px; background:var(--panel); }
.log-head{ display:flex; justify-content:space-between; align-items:baseline; margin-bottom:8px; flex-wrap:wrap; gap:8px; }
.log-role{ font-family:var(--font-display); font-weight:700; font-size:19px; }
.log-duration{ font-family:var(--font-mono); font-size:12.5px; color:var(--amber); }
.log-desc{ color:var(--ink-dim); font-size:15px; max-width:640px; margin-bottom:18px; }
.tag-row{ display:flex; gap:10px; flex-wrap:wrap; }
.tag-check{
  font-family:var(--font-mono); font-size:12px; color:var(--ink);
  border:1px solid var(--line); padding:6px 11px; border-radius:6px;
  display:inline-flex; align-items:center; gap:6px;
}
.tag-check::before{ content:"✓"; color:var(--green); }

/* ============================================================
   SKILLS
   ============================================================ */
.skills-grid{ display:grid; grid-template-columns:repeat(4,1fr); gap:1px; background:var(--line); border:1px solid var(--line); border-radius:10px; overflow:hidden; }
.skill-col{ background:var(--panel); padding:24px; }
.skill-col h3{ font-family:var(--font-mono); font-size:12px; letter-spacing:0.1em; color:var(--amber); margin-bottom:16px; }
.skill-col ul{ list-style:none; display:flex; flex-direction:column; gap:10px; }
.skill-col li{ font-size:14.5px; color:var(--ink-dim); font-family:var(--font-mono); }
.skill-col li.active{ color:var(--ink); }
.skill-col li::before{ content:"›"; color:var(--ink-faint); margin-right:8px; }

@media (max-width:860px){ .skills-grid{ grid-template-columns:repeat(2,1fr); } }
@media (max-width:500px){ .skills-grid{ grid-template-columns:1fr; } }

/* ============================================================
   PROJECTS
   ============================================================ */
.proj-grid{ display:grid; grid-template-columns:repeat(3,1fr); gap:20px; }
.proj-card{
  background:var(--panel); border:1px solid var(--line); border-radius:10px;
  padding:22px; display:flex; flex-direction:column; gap:12px;
  transition: border-color .2s, transform .2s;
}
.proj-card:hover{ border-color:var(--amber-line); transform:translateY(-3px); }
.proj-top{ display:flex; justify-content:space-between; align-items:flex-start; }
.proj-name{ font-family:var(--font-display); font-weight:700; font-size:16.5px; }
.proj-link{ font-family:var(--font-mono); font-size:11px; color:var(--ink-faint); border:1px solid var(--line); padding:4px 8px; border-radius:5px; }
.proj-link:hover{ color:var(--amber); border-color:var(--amber-line); }
.proj-desc{ font-size:13.8px; color:var(--ink-dim); flex:1; }
.proj-tech{ font-family:var(--font-mono); font-size:11px; color:var(--amber); }

@media (max-width:860px){ .proj-grid{ grid-template-columns:1fr 1fr; } }
@media (max-width:560px){ .proj-grid{ grid-template-columns:1fr; } }

/* ============================================================
   TERMINAL DOCK — signature element, persistent + functional
   ============================================================ */
#terminal-dock{
  position:fixed; bottom:20px; right:20px; z-index:800;
  width:380px; max-width:calc(100vw - 32px);
  font-family:var(--font-mono);
}
#terminal-dock .dock-header{
  display:flex; align-items:center; justify-content:space-between;
  background:var(--panel-raised); border:1px solid var(--line);
  padding:12px 16px; border-radius:10px;
  cursor:pointer;
}
#terminal-dock .dock-header .lbl{ font-size:12.5px; display:flex; align-items:center; gap:8px; }
#terminal-dock .dock-header .lbl .dot{ width:7px; height:7px; border-radius:50%; background:var(--amber); box-shadow:0 0 6px var(--amber); }
#terminal-dock .dock-header .chev{ color:var(--ink-faint); font-size:12px; transition: transform .2s; }
#terminal-dock.open .dock-header .chev{ transform:rotate(180deg); }
#terminal-dock .dock-header:hover{ border-color:var(--amber-line); }

#terminal-body{
  display:none;
  background:#0D0F13; border:1px solid var(--line); border-top:none;
  border-radius:0 0 10px 10px;
  padding:14px 16px; height:280px; overflow-y:auto;
  font-size:13px; line-height:1.7;
}
#terminal-dock.open #terminal-body{ display:block; }
#terminal-log .t-line{ margin-bottom:4px; white-space:pre-wrap; word-break:break-word; }
#terminal-log .t-prompt{ color:var(--amber); }
#terminal-log .t-out{ color:var(--ink-dim); }
#terminal-log .t-out.hl{ color:var(--green); }
#terminal-log .t-out.err{ color:var(--red); }
.term-input-row{ display:flex; align-items:center; gap:8px; margin-top:6px; }
.term-input-row .prompt-chevron{ color:var(--amber); }
#terminal-input{
  flex:1; background:transparent; border:none; color:var(--ink);
  font-family:var(--font-mono); font-size:13px; outline:none;
}

@media (max-width:520px){
  #terminal-dock{ width:calc(100vw - 32px); }
  #terminal-body{ height:220px; }
}

/* ============================================================
   CONTACT
   ============================================================ */
.contact-panel{
  border:1px solid var(--line); border-radius:12px; background:var(--panel);
  padding:44px; display:flex; flex-wrap:wrap; gap:32px; align-items:center; justify-content:space-between;
}
.contact-panel h2{ font-family:var(--font-display); font-weight:700; font-size:28px; margin-bottom:8px; }
.contact-panel .fn-line{ font-family:var(--font-mono); color:var(--amber); font-size:13px; margin-bottom:14px; }
.contact-links{ display:flex; gap:12px; flex-wrap:wrap; }

/* ============================================================
   FOOTER
   ============================================================ */
footer{ padding:40px 0; border-top:1px solid var(--line-soft); }
.footer-row{ display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:14px; }
.footer-left{ font-family:var(--font-mono); font-size:12.5px; color:var(--ink-faint); }
.footer-left b{ color:var(--ink); }
.footer-links{ display:flex; gap:18px; }
.footer-links a{ font-family:var(--font-mono); font-size:12.5px; color:var(--ink-dim); }
.footer-links a:hover{ color:var(--amber); }
.crt-toggle{
  background:none; border:none; color:var(--ink-faint); font-family:var(--font-mono);
  font-size:11px; display:flex; align-items:center; gap:6px;
}
.crt-toggle .dot{ width:6px; height:6px; border-radius:50%; background:var(--green); }
.crt-toggle:hover{ color:var(--ink); }

/* ============================================================
   TOAST (easter egg feedback)
   ============================================================ */
#toast{
  position:fixed; top:80px; left:50%; transform:translateX(-50%) translateY(-10px);
  background:var(--panel-raised); border:1px solid var(--amber-line); color:var(--amber);
  font-family:var(--font-mono); font-size:13px; padding:12px 20px; border-radius:8px;
  z-index:9500; opacity:0; pointer-events:none; transition: opacity .3s, transform .3s;
}
#toast.show{ opacity:1; transform:translateX(-50%) translateY(0); }

/* hidden panel: sudo future easter egg */
#future-panel{
  display:none;
  border:1px dashed var(--amber-line); border-radius:12px; padding:32px; margin-top:20px;
  background: linear-gradient(180deg, rgba(232,163,61,0.05), transparent);
}
#future-panel.show{ display:block; }
#future-panel .fp-label{ font-family:var(--font-mono); font-size:11px; color:var(--ink-faint); letter-spacing:0.1em; margin-bottom:10px; }
#future-panel h3{ font-family:var(--font-display); font-size:20px; margin-bottom:10px; }
#future-panel p{ color:var(--ink-dim); font-size:14.5px; max-width:560px; }
</style>
</head>
<body>

<!-- ============================================================
     BOOT SCREEN
     ============================================================ -->
<div id="boot">
  <div class="boot-inner" id="boot-lines"></div>
  <button class="skip" id="skip-btn">[ SKIP INTRO ]</button>
</div>

<!-- ============================================================
     NAV
     ============================================================ -->
<header class="site-nav">
  <div class="container nav-row">
    <div class="nav-mark">AYOUB<span>.EXE</span></div>
    <ul class="nav-links">
      <li><a href="#about">About</a></li>
      <li><a href="#experience">Experience</a></li>
      <li><a href="#projects">Projects</a></li>
      <li><a href="#skills">Skills</a></li>
      <li><a href="#contact">Contact</a></li>
    </ul>
    <div class="nav-status"><span class="dot"></span> OPEN TO OPPORTUNITIES</div>
  </div>
</header>

<!-- ============================================================
     HERO
     ============================================================ -->
<section class="hero">
  <div class="container hero-grid">
    <div>
      <div class="eyebrow">Web Developer · Agadir, Morocco</div>
      <h1 class="hero-title">Ayoub Rechouk</h1>
      <div class="hero-role">Web Development Student <span class="sep">/</span> Building my way into the industry</div>
      <p class="hero-copy">Student developer focused on web development, building practical projects and continuously expanding my technical skills across PHP, Python, JavaScript and MySQL.</p>
      <div class="status-pill"><span class="dot"></span> OPEN TO OPPORTUNITIES</div>
      <div class="hero-actions">
        <a href="#projects" class="btn btn-primary">View Projects</a>
        <a href="https://github.com/ayoubrechouk" target="_blank" rel="noopener" class="btn btn-ghost">GitHub</a>
        <a href="https://www.linkedin.com/in/ayoub-rechouk-586260336/" target="_blank" rel="noopener" class="btn btn-ghost">LinkedIn</a>
        <a href="#contact" class="btn btn-ghost">Contact</a>
      </div>
    </div>
    <div class="hero-photo-wrap">
      <div class="frame-label">PORTRAIT<span>.2026</span></div>
      <div class="grid-overlay"></div>
      <div class="scanline"></div>
