<div id="terminal-dock" role="region" aria-label="Interactive terminal">
  <div class="dock-header" id="dock-header" tabindex="0" role="button" aria-expanded="false">
    <span class="lbl"><span class="dot"></span> terminal — type 'help'</span>
    <span class="chev">▲</span>
  </div>
