    </div>
  </div>
</div>

<div id="toast" role="status" aria-live="polite"></div>

<script>
(function(){
  "use strict";

  /* ---------- hidden console joke ---------- */
  console.log("%cYes, I inspected the console too.", "color:#E8A33D; font-family:monospace; font-size:13px;");

  /* ---------- BOOT SEQUENCE ---------- */
  var bootEl = document.getElementById('boot');
  var bootLines = document.getElementById('boot-lines');
  var skipBtn = document.getElementById('skip-btn');
  var seen = sessionStorage.getItem('ayoub_boot_seen');

  var lines = [
    "AYOUB.EXE",
    "INITIALIZING...",
    "",
    "DIGITAL JOURNEY DETECTED",
    "LOCATION: AGADIR, MOROCCO",
    "STATUS: DEVELOPER IN TRAINING",
    "",
    "BOOTING...",
    "  loading identity......... OK",
    "  loading education......... OK",
    "  loading experience......... OK",
    "  loading projects......... OK",
    "  loading curiosity......... OK",
    "  loading ambition......... OK",
    "",
    "SYSTEM READY."
  ];

  function finishBoot(){
    bootEl.classList.add('hide');
    setTimeout(function(){ bootEl.style.display = 'none'; }, 550);
    sessionStorage.setItem('ayoub_boot_seen', '1');
  }

  if (seen){
    bootEl.style.display = 'none';
  } else {
    var i = 0;
    function typeLine(){
      if (i >= lines.length){
        var enter = document.createElement('div');
        enter.className = 'boot-line';
        enter.innerHTML = '<span class="cursor"></span>  <span style="color:#8FE39A;">[ ENTER ]</span> to continue';
        bootLines.appendChild(enter);
        enter.style.cursor = 'pointer';
        enter.addEventListener('click', finishBoot);
        document.addEventListener('keydown', function onKey(e){
          if (e.key === 'Enter'){ finishBoot(); document.removeEventListener('keydown', onKey); }
        });
        return;
      }
      var d = document.createElement('div');
      d.className = 'boot-line';
      d.textContent = lines[i];
      bootLines.appendChild(d);
      i++;
      setTimeout(typeLine, lines[i-1] === "" ? 90 : 130);
    }
    typeLine();
    setTimeout(function(){ skipBtn.classList.add('show'); }, 1800);
    skipBtn.addEventListener('click', finishBoot);
  }

  /* ---------- TOAST ---------- */
  var toastEl = document.getElementById('toast');
  var toastTimer;
  function showToast(msg){
    toastEl.textContent = msg;
    toastEl.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function(){ toastEl.classList.remove('show'); }, 3200);
  }

  /* ---------- CRT TOGGLE ---------- */
  var crtBtn = document.getElementById('crt-toggle-btn');
  function setCrt(on){
    document.body.classList.toggle('crt-on', on);
    crtBtn.setAttribute('aria-pressed', on ? 'true' : 'false');
  }
  crtBtn.addEventListener('click', function(){
    var on = !document.body.classList.contains('crt-on');
    setCrt(on);
    showToast(on ? 'CRT DISPLAY: ON' : 'CRT DISPLAY: OFF');
  });

  /* ---------- KONAMI CODE EASTER EGG ---------- */
  var konami = ['ArrowUp','ArrowUp','ArrowDown','ArrowDown','ArrowLeft','ArrowRight','ArrowLeft','ArrowRight'];
  var kIndex = 0;
  document.addEventListener('keydown', function(e){
    if (e.key === konami[kIndex]){
      kIndex++;
      if (kIndex === konami.length){
        kIndex = 0;
        setCrt(true);
        showToast('DEVELOPER MODE ACTIVATED — CRT DISPLAY ENABLED');
      }
    } else {
      kIndex = (e.key === konami[0]) ? 1 : 0;
    }
  });

  /* ---------- TERMINAL ---------- */
  var dock = document.getElementById('terminal-dock');
  var dockHeader = document.getElementById('dock-header');
  var termLog = document.getElementById('terminal-log');
  var termInput = document.getElementById('terminal-input');

  function toggleDock(){
    var open = dock.classList.toggle('open');
    dockHeader.setAttribute('aria-expanded', open ? 'true' : 'false');
    if (open) setTimeout(function(){ termInput.focus(); }, 50);
  }
  dockHeader.addEventListener('click', toggleDock);
  dockHeader.addEventListener('keydown', function(e){
    if (e.key === 'Enter' || e.key === ' '){ e.preventDefault(); toggleDock(); }
  });

  function printLine(text, cls){
    var d = document.createElement('div');
    d.className = 't-line ' + (cls || 't-out');
    d.textContent = text;
    termLog.appendChild(d);
    termLog.parentElement.scrollTop = termLog.parentElement.scrollHeight;
  }
  function printPrompt(cmd){
    var d = document.createElement('div');
    d.className = 't-line t-prompt';
    d.textContent = '$ ' + cmd;
    termLog.appendChild(d);
  }

  var commands = {
    help: function(){
      printLine('Available commands:');
      ['whoami','about','skills','projects','education','experience','github','linkedin','contact','sudo future','clear'].forEach(function(c){
        printLine('  ' + c);
      });
    },
    whoami: function(){ printLine('ayoubrechouk'); },
    about: function(){ printLine('Web development student, Agadir, Morocco. Learning by building.'); },
    skills: function(){ printLine('HTML, CSS, JavaScript, PHP, MySQL, Python — currently deepening React, Laravel, backend.'); },
    projects: function(){
      printLine('see · portfolio · Recipe · aubeflower · game1 · Playlist-for-prof', 't-out hl');
      printLine('→ scroll to Project Database, or github.com/ayoubrechouk');
    },
    education: function(){
      printLine('2025–2027  Institut Supérieur de Technologie Appliquée — Web Development (current)');
      printLine('2021–2024  Ibn Zohr University — Economics, Bac+2');
    },
    experience: function(){ printLine('Informatique / Bureautique — Trainee, 2 months.'); },
    github: function(){ printLine('https://github.com/ayoubrechouk'); },
    linkedin: function(){ printLine('https://www.linkedin.com/in/ayoub-rechouk-586260336/'); },
    contact: function(){ printLine('ayoubrechouk2004@gmail.com'); },
    goal: function(){ printLine('Build. Learn. Ship. Repeat.'); },
    clear: function(){ termLog.innerHTML = ''; },
    '404': function(){
      printLine('404', 't-out err');
      printLine('BORING PORTFOLIO NOT FOUND.', 't-out err');
    }
  };

  function runCommand(raw){
    var cmd = raw.trim();
    printPrompt(cmd);
    if (!cmd) return;
    var lc = cmd.toLowerCase();
    if (lc === 'sudo future'){
      printLine('ACCESS GRANTED.', 't-out hl');
      var fp = document.getElementById('future-panel');
      fp.classList.add('show');
      showToast('ACCESS GRANTED — scroll to Contact section');
      return;
    }
    if (lc === 'cd /nowhere' || lc === 'cd nowhere'){
      commands['404']();
      return;
    }
    if (commands[lc]){
      commands[lc]();
    } else {
      printLine('command not found: ' + cmd + ' — type "help"', 't-out err');
    }
  }

  termInput.addEventListener('keydown', function(e){
    if (e.key === 'Enter'){
      var val = termInput.value;
      termInput.value = '';
      runCommand(val);
    }
  });

  // seed terminal with a welcome line
  printLine('Type "help" to see available commands.');

})();
</script>
</body>
</html>